export async function consumeImageBuildFinalizationBatch(
  batch: MessageBatch<unknown>,
  process: FinalizationProcessor
): Promise<void> {
  for (const message of batch.messages) {
    const parsed = imageBuildFinalizationJobSchema.safeParse(message.body);
    if (!parsed.success) {
      logger.error("image_build.finalization_job_invalid", {
        queue_message_id: message.id,
        attempts: message.attempts,
      });
      message.ack();
      continue;
    }

    try {
      const result = await process(parsed.data, message.id);
      if (result.type === "retry") {
        message.retry({ delaySeconds: result.delaySeconds });
      } else {
        message.ack();
      }
    } catch (error) {
      logger.error("image_build.finalization_error", {
        build_id: parsed.data.buildId,
        queue_message_id: message.id,
        attempts: message.attempts,
        error: error instanceof Error ? error : new Error(String(error)),
      });
      message.retry({ delaySeconds: IMAGE_BUILD_FINALIZATION_RETRY_DELAY_SECONDS });
    }
  }
}

function instrumentStatement(stmt: SqlStatement, metrics: RequestMetrics): SqlStatement {
  const wrapper: WrappedStatement = {
    bind(...values: unknown[]): SqlStatement {
      return instrumentStatement(stmt.bind(...values), metrics);
    },

    async first<T = Record<string, unknown>>(): Promise<T | null> {
      const start = Date.now();
      const result = await stmt.first<T>();
      metrics.d1Queries.push({ query_ms: Date.now() - start });
      return result;
    },

    async run<T = Record<string, unknown>>(): Promise<SqlResult<T>> {
      const start = Date.now();
      const result = await stmt.run<T>();
      metrics.d1Queries.push({
        query_ms: Date.now() - start,
        d1_server_ms: result.meta?.duration,
        rows_read: result.meta?.rows_read,
        rows_written: result.meta?.rows_written,
      });
      return result;
    },

    async all<T = Record<string, unknown>>(): Promise<SqlResult<T>> {
      const start = Date.now();
      const result = await stmt.all<T>();
      metrics.d1Queries.push({
        query_ms: Date.now() - start,
        d1_server_ms: result.meta?.duration,
        rows_read: result.meta?.rows_read,
        rows_written: result.meta?.rows_written,
      });
      return result;
    },
  };

  wrapper[ORIGINAL_STMT] = stmt;
  return wrapper;
}

