function claimKey(repo: RepoIdentity): string {
  return `${repo.repoOwner.toLowerCase()}/${repo.repoName.toLowerCase()}`;
}

/**
 * In-flight PR creation claims, one per target repository. PR creation spans
 * several awaits (push, provider calls) during which the DO serves other
 * requests, so the persisted-artifact scan alone cannot enforce one PR per
 * repo — two concurrent requests could both pass it. Claims are in-memory on
 * the DO instance: a claim's lifetime is its request's, and both die with
 * the instance.
 */
export class PullRequestCreationClaims {
  private readonly inFlight = new Set<string>();

  /** True when the claim was acquired; false when creation is already in flight. */
  claim(repo: RepoIdentity): boolean {
    const key = claimKey(repo);
    if (this.inFlight.has(key)) return false;
    this.inFlight.add(key);
    return true;
  }

  release(repo: RepoIdentity): void {
    this.inFlight.delete(claimKey(repo));
  }
}
  async createPullRequest(input: CreatePullRequestInput): Promise<CreatePullRequestResult> {
    const session = this.deps.repository.getSession();
    if (!session) {
      return { kind: "error", status: 404, error: "Session not found" };
    }
    if (!session.repo_owner || !session.repo_name) {
      return { kind: "error", status: 400, error: "Pull requests require a repository context" };
    }

    // Re-resolved here even though the handler already validated the target:
    // this is a sandbox-auth security boundary, so the service must not
    // trust its caller (defense in depth).
    let target: SessionRepositoryEntry;
    try {
      target = resolveSessionRepositoryTarget(input, this.deps.repository.getSessionRepositories());
    } catch (error) {
      const mapped = mapRepositoryTargetError(error);
      if (!mapped) throw error;
      return { kind: "error", ...mapped };
    }
    const memberRow = target.row;
    const isPrimary = target.isPrimary;
    const targetRepo = { repoOwner: target.repoOwner, repoName: target.repoName };

    this.deps.log.info("Creating PR", {
      user_id: input.promptingUserId,
      repo_owner: targetRepo.repoOwner,
      repo_name: targetRepo.repoName,
    });

    if (!this.deps.claims.claim(targetRepo)) {
      return {
        kind: "error",
        status: 409,
        error: `A pull request is already being created for ${targetRepo.repoOwner}/${targetRepo.repoName} in this session.`,
      };
    }
    try {
    } catch (error) {
      this.deps.log.error("PR creation failed", {
        error: error instanceof Error ? error : String(error),
      });

      if (error instanceof PullRequestCreationError) {
        return { kind: "error", status: error.status, error: error.message };
      }

      if (error instanceof SourceControlProviderError) {
        return {
          kind: "error",
          status: error.httpStatus || 500,
          error: error.message,
        };
      }

      return {
        kind: "error",
        status: 500,
        error: error instanceof Error ? error.message : "Failed to create PR",
      };
    } finally {
      this.deps.claims.release(targetRepo);
    }

async runComplete(body: AutomationRunCompletion): Promise<void> {
  const store = new AutomationStore(this.db);

  const run = await store.getRunById(body.automationId, body.runId);
  if (!run) {
    this.log.warn("Ignoring run-complete callback for non-active run", {
      event: "scheduler.run_complete_ignored",
      automation_id: body.automationId,
      run_id: body.runId,
      current_status: "not_found",
    });
    return;
  }

  // SQL-guarded transition: only an active run may go terminal. When the
  // guard suppresses the write (recovery sweep or a concurrent callback got
  // there first) the callback is acknowledged as ignored — a terminal child
  // must never transition again.
  const transitioned = await store.updateRun(
    body.runId,
    body.success
      ? { status: "completed", completed_at: Date.now() }
      : {
          status: "failed",
          failure_reason: body.error || "Unknown error",
          completed_at: Date.now(),
        }
  );

  if (!transitioned) {
    this.log.warn("Ignoring run-complete callback for non-active run", {
      event: "scheduler.run_complete_ignored",
      automation_id: body.automationId,
      run_id: body.runId,
      current_status: run.status,
    });
    return;
  }

  // Invocation-level accounting: one CAS-guarded strike per invocation on
  // first failure; streak reset once every sibling completed.
  await this.applyInvocationAccounting(store, body.automationId, run.invocation_id);

  if (body.success) {
    this.log.info("Run completed successfully", {
      event: "scheduler.run_complete",
      automation_id: body.automationId,
      run_id: body.runId,
      session_id: body.sessionId,
    });
  } else {
    this.log.warn("Run completed with failure", {
      event: "scheduler.run_failed",
      automation_id: body.automationId,
      run_id: body.runId,
      session_id: body.sessionId,
      error: body.error,
    });
  }

  // Slack-triggered runs post the agent's result into the triggering message's
  // thread and clear the `eyes` reaction when they finish. The scheduler owns
  // this fan-out (not the session callback path) because the message
  // coordinates live on the invocation. Best-effort.
  const invocation = await store.getInvocationById(run.invocation_id);
  const slackMeta = parseSlackTriggerMetadata(invocation?.trigger_metadata ?? null);
  if (slackMeta) {
    const automation = await store.getById(body.automationId);
    await this.notifySlackCompletion(run, slackMeta, {
      sessionId: body.sessionId,
      messageId: body.messageId,
      success: body.success,
      error: body.error,
      repoFullName: formatRunRepositoryLabel(run),
      model: automation?.model ?? "",
      reasoningEffort: automation?.reasoning_effort ?? undefined,
    });
  }
}

## Browser Authentication

The control plane is the browser authentication authority and runs exact-pinned Better Auth. The
Next.js web app is a BFF: it proxies a small `/api/auth/*` allowlist with its `sig1` service
credential and never stores provider secrets.

Browser resource requests require both the signed `service:web` channel and Better Auth's opaque
session cookie. The application principal is the canonical `users.id`, and the authentication
context contains only the browser-session and signed-channel evidence. Provider-specific credential
authorities resolve linked accounts on demand for workflows such as GitHub SCM enrichment; linked
accounts do not participate in browser-session authentication.

Terraform configures `WEB_APP_URL`, provider credentials, admission allowlists, and
`BROWSER_AUTH_SECRET` on this worker. `WEB_APP_URL` must be the exact browser-visible HTTPS origin,
except that an HTTP loopback origin is accepted for local development.

A complete GitHub or Google OAuth credential pair enables that sign-in provider; partial pairs and
an empty provider set fail closed. Google requires verified-email/domain admission (or explicit
unsafe allow-all), while GitHub may also use username or organization admission. The normalized
runtime constructs Better Auth and the immutable provider list from the same configuration.
`GET /internal/auth/sign-in-providers` exposes only those identifiers to signed `service:web`
requests so the React `/login` route can render them server-side.
export async function authenticate(
  request: Request,
  env: Env,
  ctx: RequestContext,
  requirement: AuthenticationRequirement = {}
): Promise<AuthResult> {
  const signatureHeader = request.headers.get(SERVICE_SIGNATURE_HEADER);
  if (signatureHeader !== null) {
    const channel = await authenticateServiceRequest(request, env, ctx, signatureHeader);
    if (
      isAuthError(channel) ||
      channel.principal.kind !== "service" ||
      channel.principal.service !== "web" ||
      requirement.webService !== "user"
    ) {
      return channel;
    }
    if (!ctx.getUserAuth) {
      logger.error("User authentication runtime unavailable", {
        event: "auth.browser.misconfigured",
        request_id: ctx.request_id,
        trace_id: ctx.trace_id,
      });
      return {
        reason: "User authentication is not configured",
        status: 500,
        failedScheme: "browser-session",
      };
    }
    try {
      const userSession = await authenticateSession(ctx.getUserAuth().api, channel.request.headers);
      if (!userSession) {
        return {
          reason: "Unauthorized",
          status: 401,
          failedScheme: "browser-session",
        };
      }
      return {
        principal: { kind: "user", userId: userSession.userId },
        authentication: userSession.authentication,
        request: channel.request,
      };
    } catch (cause) {
      logger.error("User session validation failed", {
        event: "auth.browser.failed",
        failure: cause instanceof SessionIntegrityError ? "integrity" : "runtime",
        error: cause,
        request_id: ctx.request_id,
        trace_id: ctx.trace_id,
      });
      return {
        reason: "User authentication failed",
        status: 500,
        failedScheme: "browser-session",
      };
    }
  }

  return { reason: "Unauthorized", status: 401, failedScheme: "none" };
}
export async function authenticateSession(
  sessionReader: SessionReader,
  headers: Headers
): Promise<AuthenticatedUserSession | null> {
  // Resource authentication is a read-only hot path, not a session-lifecycle endpoint.
  const candidate = await sessionReader.getSession({
    headers,
    query: { disableRefresh: true },
  });
  if (candidate === null) return null;

  const parsedSession = sessionSchema.safeParse(candidate);
  if (!parsedSession.success) {
    throw new SessionIntegrityError("Better Auth returned a malformed session");
  }
  const { session, user } = parsedSession.data;
  if (session.userId !== user.id) {
    throw new SessionIntegrityError("Better Auth returned a cross-user session");
  }

  return {
    userId: user.id,
    authentication: {
      mechanism: "browser_session",
      credentialId: session.id,
      channel: {
        kind: "sig1",
        service: "web",
      },
    },
  };
}

/**
 * Edge authentication: resolve every non-public, non-sandbox request to a
 * typed `Principal` before any handler runs.
 *
 * A `sig1` service signature is verified against that service's own secret.
 * User requests additionally require a Better Auth session. Anything else
 * is not a recognized credential.
 *
 * Sandbox tokens stay router-verified (they need the session id from the
 * path and a DO round-trip), so they are not dispatched here.
/**
 * Validate sandbox authentication by checking with the Durable Object.
 * The DO stores the expected sandbox auth token.
 *
 * On success, sets the sandbox principal on the request context — this is
 * the single place a sandbox principal is assembled.
 *
 * @param request - The incoming request
 * @param env - Environment bindings
 * @param sessionId - Session ID extracted from path
 * @param ctx - Request correlation context
 * @returns null if authentication passes, or an error Response to return immediately
 */
async function verifySandboxAuth(
  request: Request,
  env: Env,
  sessionId: string,
  ctx: RequestContext
): Promise<Response | null> {
  const authHeader = request.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return error("Unauthorized: Missing sandbox token", 401);
  }

  const token = authHeader.slice(7); // Remove "Bearer " prefix

  // Ask the Session runtime to validate this sandbox token.
  const verifyResponse = await createSessionRuntimeClient(env, ctx).fetch(
    sessionId,
    SessionInternalPaths.verifySandboxToken,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ token }),
    }
  );

  if (!verifyResponse.ok) {
    const clientIP = request.headers.get("CF-Connecting-IP") || "unknown";
    logger.warn("Auth failed: sandbox", {
      event: "auth.sandbox_failed",
      http_path: new URL(request.url).pathname,
      client_ip: clientIP,
      session_id: sessionId,
      request_id: ctx.request_id,
      trace_id: ctx.trace_id,
    });
    return error("Unauthorized: Invalid sandbox token", 401);
  }

  ctx.principal = { kind: "sandbox", sessionId };
  return null; // Auth passed

