/**
 * Routes validated sandbox events to their family handlers. Owns exactly the
 * cross-family concerns: arrival logging, the per-event context (one clock
 * reading, one message-attribution resolution), and the delivery-ack
 * contract — the ack for a critical event is sent after its handler finishes,
 * and family handlers never see `ackId`.
 */
export class SessionSandboxEventProcessor {
  constructor(
    private readonly log: Logger,
    private readonly messageRepository: MessageRepository,
    private readonly wsManager: SessionWebSocketManager,
    private readonly streaming: SandboxStreamingEventHandler,
    private readonly artifacts: SandboxArtifactEventHandler,
    private readonly execution: SandboxExecutionEventHandler,
    private readonly runtime: SandboxRuntimeEventHandler,
    private readonly pushService: SandboxPushService
  ) {}

  async processSandboxEvent(event: SandboxEventWithAck): Promise<void> {
    if (event.type === "heartbeat" || event.type === "token") {
      this.log.debug("Sandbox event", { event_type: event.type });
    } else if (event.type !== "execution_complete") {
      this.log.info("Sandbox event", { event_type: event.type });
    }

    const now = Date.now();
    const eventMessageId = "messageId" in event ? event.messageId : null;
    const processingMessage = this.messageRepository.getProcessingMessage();
    const context: SandboxEventContext = {
      now,
      messageId: eventMessageId ?? processingMessage?.id ?? null,
      processingMessage,
    };

    await this.dispatch(event, context);

    if (CRITICAL_EVENT_TYPES.has(event.type)) {
      this.sendAck(event.ackId);
    }

/**
 * Durable Object alarm handler.
 *
 * Checks for stuck processing messages (defense-in-depth execution timeout)
 * before delegating to lifecycle alarm processing.
 */
export function createAlarmHandler(deps: AlarmHandlerDeps): AlarmHandler {
  return {
    async handle(): Promise<void> {
      await deps.messageQueue.recoverStopConfirmationTimeout();
      // Execution timeout check: if a message has been in 'processing' longer than
      // the configured timeout, fail it. This is idempotent - if the message was
      // already failed (by lifecycle recovery or a prior alarm),
      // getProcessingMessageWithStartedAt() returns null.
      const processing = deps.repository.getProcessingMessageWithStartedAt();
      if (processing?.started_at) {
        const now = deps.now();
        const executionTimeoutMs = deps.getExecutionTimeoutMs();
        const result = evaluateExecutionTimeout(
          processing.started_at,
          { timeoutMs: executionTimeoutMs },
          now
        );
        if (result.isTimedOut) {
          deps.log.warn("Execution timeout: message stuck in processing", {
            event: "execution.timeout",
            message_id: processing.id,
            elapsed_ms: result.elapsedMs,
            timeout_ms: executionTimeoutMs,
          });
          await deps.messageQueue.failStuckProcessingMessage();
        } else {
          // An earlier lifecycle alarm has consumed the Durable Object's single
          // alarm slot. Reassert this message's deadline before lifecycle handling
          // schedules its next check so stuck-message recovery cannot be delayed.
          await deps.alarmScheduler.schedule(processing.started_at + executionTimeoutMs);
        }
      }

      const lifecycleResult = await deps.lifecycleManager.handleAlarm();
      if (lifecycleResult !== "no_action") {
        await deps.messageQueue.failStuckProcessingMessage();
      }
      if (lifecycleResult === "sandbox_terminated") {
        await deps.messageQueue.resumeAfterSandboxTermination();
      }
  /**
   * Durable Object alarm handler. Initializes without re-arming the alarm —
   * this delivery is the alarm — then delegates deadline handling.
   */
  async alarm(): Promise<void> {
    this.ensureInitialized(false);
    await this._runtime!.server.onScheduledDeadline();
  }

