    wsManager,
    sessionCoreRepository,
    sandboxRepository,
    lifecycleManager,
    messenger,
    backgroundTasks,
    messageQueue,
  } = this.deps;
  log.debug("WebSocket upgrade requested");
  const isSandbox = url.searchParams.get("type") === "sandbox";

  // Validate sandbox authentication
  if (isSandbox) {
    const wsStartTime = Date.now();
    const authHeader = request.headers.get("Authorization");
    const sandboxId = request.headers.get("X-Sandbox-ID");
    const providedToken = authHeader?.startsWith("Bearer ")
      ? authHeader.slice("Bearer ".length)
      : null;

    // Get expected values from DB
    const sandbox = sandboxRepository.getSandbox();
    const expectedSandboxId = sandbox?.modal_sandbox_id;

    // Validate sandbox ID first (catches stale sandboxes reconnecting after restore)
    if (expectedSandboxId && sandboxId !== expectedSandboxId) {
      log.warn("ws.connect", {
        event: "ws.connect",
        ws_type: "sandbox",
        outcome: "auth_failed",
        reject_reason: "sandbox_id_mismatch",
        expected_sandbox_id: expectedSandboxId,
        sandbox_id: sandboxId,
        duration_ms: Date.now() - wsStartTime,
      });
      return new Response("Forbidden: Wrong sandbox ID", { status: 403 });
    }

    // Validate auth token
    const tokenMatches = await isValidSandboxToken(providedToken, sandbox);
    if (!tokenMatches) {
      log.warn("ws.connect", {
        event: "ws.connect",
        ws_type: "sandbox",
        outcome: "auth_failed",
        reject_reason: "token_mismatch",
        duration_ms: Date.now() - wsStartTime,
      });
      return new Response("Unauthorized: Invalid auth token", { status: 401 });
    }

    // Reject connection if the session itself is closed for good. Narrower
    // than "not active": `completed` and `failed` sessions are idle, not
    // over — warm-on-typing spawns a sandbox for one before the follow-up
    // prompt arrives, and rejecting its bridge stranded that prompt.
    //
    // Read after authentication, not before: token hashing is a non-storage
    // await, so the input gate lets a cancel or archive land while this
    // request is suspended. Admission needs a fresh, synchronous read.
    const currentSession = sessionCoreRepository.getSession();
    if (currentSession && !isSessionPromptable(currentSession.status)) {
      log.warn("ws.connect", {
        event: "ws.connect",
        ws_type: "sandbox",
        outcome: "rejected",
        reject_reason: "session_terminal",
        session_status: currentSession.status,
        duration_ms: Date.now() - wsStartTime,
      });
      return new Response("Session is terminal", { status: 410 });
    }

    const currentSandbox = sandboxRepository.getSandbox();
    // Deliberately narrower than isDeadSandboxStatus: a "failed" sandbox may
    // still connect after a slow boot and self-heal by becoming ready.
    if (currentSandbox && isSandboxReconnectBlockedStatus(currentSandbox.status)) {
      log.warn("ws.connect", {
        event: "ws.connect",
        ws_type: "sandbox",
        outcome: "rejected",
        reject_reason: "sandbox_stopped",
        sandbox_status: currentSandbox.status,
        duration_ms: Date.now() - wsStartTime,
      });
      return new Response("Sandbox is stopped", { status: 410 });
    }
    if (
      currentSandbox?.modal_sandbox_id !== expectedSandboxId ||
      currentSandbox?.auth_token_hash !== sandbox?.auth_token_hash ||
      currentSandbox?.auth_token !== sandbox?.auth_token
    ) {
      return new Response("Forbidden: Sandbox credentials changed", { status: 403 });
    }

    // Auth passed — continue to WebSocket accept below
    // The success ws.connect event is emitted after the WebSocket is accepted
  }
async dispatch(request: Request): Promise<Response> {
  const fetchStart = this.deps.clock.monotonicNowMs();
  const log = this.requestLogger(request);
  const url = new URL(request.url);
  const path = url.pathname;

  // Preserve the existing contract: upgrades and unmatched routes are not route metrics.
  if (request.headers.get("Upgrade") === "websocket") {
    return this.deps.handleWebSocketUpgrade(request, url, log);
  }

  const route = this.deps.routes.find(
    (candidate) => candidate.path === path && candidate.method === request.method
  );
  if (!route) return new Response("Not Found", { status: 404 });

  /**
   * Atomically consumes a fresh callback token and persists success metadata.
   * An exact duplicate is reported as a replay; any conflicting or stale
   * callback is rejected without changing the row.
   */
  async acceptSuccessfulCompletion(params: {
    buildId: string;
    provider: ImageBuildProvider;
    providerSessionId: string;
    tokenHash: string;
    completionHash: string;
    repositoryShas: RepositoryShaEntry[];
    runtimeVersion: string;
    buildDurationSeconds: number;
    now: number;
  }): Promise<ImageBuildCompletionAcceptance> {
    const result = await this.db
      .prepare(
        `UPDATE image_builds
         SET completion_hash = ?,
             repository_shas = ?,
             runtime_version = ?,
             build_duration_seconds = ?,
             callback_token_used_at = ?
         WHERE id = ? AND provider = ? AND provider_session_id = ? AND status = 'building'
           AND callback_token_hash = ?
           AND callback_token_expires_at >= ?
           AND callback_token_used_at IS NULL`
      )
      .bind(
        params.completionHash,
        JSON.stringify(params.repositoryShas),
        params.runtimeVersion,
        params.buildDurationSeconds,
        params.now,
        params.buildId,
        params.provider,
        params.providerSessionId,
        params.tokenHash,
        params.now
      )
      .run();

    if ((result.meta?.changes ?? 0) > 0) return "accepted";
    return this.readReplayAcceptance(params);
  }
/**
 * Callback authentication for image builds.
 *
 * Every build callback authenticates with the single-use bearer token minted
 * at trigger time; only its HMAC hash is stored on the build row. The store
 * additionally binds every token to the exact provider session. Helpers here
 * are log-free; the workflow logs failures and maps them to the route-facing
 * error taxonomy.
 */

import { computeHmacHex } from "@open-inspect/shared/auth";
import type { Env } from "../types";

export const IMAGE_BUILD_CALLBACK_TOKEN_TTL_MS = 2 * 60 * 60 * 1000;
const IMAGE_BUILD_CALLBACK_TOKEN_PATTERN = /^[a-f0-9]{64}$/;

export function generateImageBuildCallbackToken(): string {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return Array.from(bytes)
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

async function hashWithPepper(token: string, pepper: string): Promise<string> {
  // The "repo-image-callback:" domain-separation prefix is WIRE/STORAGE-FROZEN:
  // it is baked into every stored callback_token_hash, so changing it would
  // invalidate all in-flight build callbacks. Only surrounding identifiers
  // rename; the literal never does.
  return computeHmacHex(`repo-image-callback:${token}`, pepper);
}

/** Hash a callback token for STORAGE, always under the primary pepper. */
export async function hashImageBuildCallbackToken(token: string, env: Env): Promise<string> {
  if (!env.IMAGE_CALLBACK_TOKEN_PEPPER) {
    throw new Error("IMAGE_CALLBACK_TOKEN_PEPPER is required for image build callback hashing");
  }
  return hashWithPepper(token, env.IMAGE_CALLBACK_TOKEN_PEPPER);
}

/**
 * Extract a well-formed callback bearer token from the request, or null when
 * the Authorization header is absent or not token-shaped.
 */
export function getImageBuildCallbackBearerToken(request: Request): string | null {
  const authHeader = request.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) return null;
  const token = authHeader.slice(7).trim();
  if (!token || !IMAGE_BUILD_CALLBACK_TOKEN_PATTERN.test(token)) return null;
  return token;
}

/**
 * "rejected" is an authentication failure (missing/expired/forged token);
 * "misconfigured" means the deployment cannot authenticate anything (no
 * callback-token pepper bound).
 */
export type ImageBuildCallbackAuthFailure = "rejected" | "misconfigured";

